// Me: The account behind the credential.
type Me struct {
	// Your account id. Trades, settlements and balances are scoped to it.
	AccountID string `json:"account_id,omitempty"`
	// Path of your avatar, `/avatars/{handle}.svg`, relative to the API host.
	// `null` when `handle` is `null`.
	AvatarURL string `json:"avatar_url,omitempty"`
	// First name on the account, or `null` if no profile is loaded.
	FirstName string `json:"first_name,omitempty"`
	// Your public handle, shown on the leaderboard in place of your name. `null`
	// until one is set.
	Handle string `json:"handle,omitempty"`
	// When you may next change your handle. `null` means now; otherwise the end of
	// the 30-day window since the last change.
	HandleChangeableAt time.Time `json:"handle_changeable_at,omitzero"`
	// The id of the API key that signed this request: the value sent in the
	// access-key header. `null` on a bearer request.
	KeyID string `json:"key_id,omitempty"`
	// Last name on the account, or `null` if no profile is loaded.
	LastName string `json:"last_name,omitempty"`
	// Whether you have consented to appear on public leaderboards. New accounts
	// start with the jurisdiction's default; accounts from before the leaderboard
	// start at `false`. Change it with `PATCH /api/v1/me/profile`.
	LeaderboardOptIn bool `json:"leaderboard_opt_in,omitempty"`
	// How this request authenticated: `api_key` for a signed request, `bearer` for
	// a session token. One of: "api_key", "bearer".
	Method string `json:"method,omitempty"`
	// Access level granted to this key: `read_only`, or `read_write` for keys that
	// may place and cancel orders. `null` on a bearer request. One of:
	// "read_only", "read_write".
	Scope string `json:"scope,omitempty"`
	// Your user id. Substitute this into account channel topics such as
	// `orders:{user_id}`.
	UserID string `json:"user_id,omitempty"`
}

// Order: An order resting on, or already matched against, the exchange book.
type Order struct {
	// When the matching engine accepted the order. `null` while the order is still
	// pending. UNIX microseconds.
	AcceptedAt int64 `json:"accepted_at,omitempty"`
	// The action of the order, either `buy` or `sell`. One of: "buy", "sell".
	Action string `json:"action,omitempty"`
	// Order size in dollars, for an order entered by amount rather than by
	// contract quantity. `null` for orders placed through this API, which always
	// take a quantity. Money as a decimal string, exactly as sent by the API.
	Amount Decimal `json:"amount,omitempty"`
	// Volume-weighted average fill price. `null` until the order has its first
	// fill. In dollars. Money as a decimal string, exactly as sent by the API.
	AvgPrice Decimal `json:"avg_price,omitempty"`
	// The cancellation reason, if the order was cancelled.
	CancellationReason string `json:"cancellation_reason,omitempty"`
	// Your own identifier, echoed back unchanged, or `null` if you sent none. A
	// free-form string, not a UUID, and set by REST and FIX callers alike.
	ClientOrderID string `json:"client_order_id,omitempty"`
	// The extended deadline for a delayed order. UNIX microseconds.
	DelayedUntil int64 `json:"delayed_until,omitempty"`
	// The device from which this order was placed.
	DeviceID string `json:"device_id,omitempty"`
	// The expiration condition for the order. One of: "good_till_start",
	// "good_till_time".
	Expiration string `json:"expiration,omitempty"`
	// The expiration time for time-based expiration. UNIX microseconds.
	ExpirationTime int64 `json:"expiration_time,omitempty"`
	// When the contracts this order trades expire, as UNIX microseconds: the
	// market's expiration, copied onto the order when it is placed. `null` when
	// the market has no event. Not the same as `expiration_time`.
	ExpiresAt int64 `json:"expires_at,omitempty"`
	// Contracts filled so far. Compare with `quantity` to get remaining size.
	// Quantity as a decimal string, exactly as sent by the API.
	Filled Decimal `json:"filled,omitempty"`
	// The portion of `amount` that has been filled. In dollars. Money as a decimal
	// string, exactly as sent by the API.
	FilledAmount Decimal `json:"filled_amount,omitempty"`
	// The percentage of the contracts on the order that have been filled. A
	// percentage, not money.
	FilledPercentage int64 `json:"filled_percentage,omitempty"`
	// True if the order arrived over FIX rather than REST.
	FixOrder bool `json:"fix_order,omitempty"`
	// Unique identifier for the record.
	ID string `json:"id,omitempty"`
	// Creation time, as UNIX microseconds.
	InsertedAt int64 `json:"inserted_at,omitempty"`
	// The IP address from which this order was placed.
	IPAddress string `json:"ip_address,omitempty"`
	// The market this record relates to.
	MarketID string `json:"market_id,omitempty"`
	// Legacy. The odds format (`decimal` or `american`) an order was entered in on
	// an STX app. `null` for orders placed through this API.
	OddsType string `json:"odds_type,omitempty"`
	// Legacy. The odds an order was entered at on an STX app, as a string. `null`
	// for orders placed through this API.
	OddsValue string `json:"odds_value,omitempty"`
	// The type of order, either `limit` or `market`. One of: "limit", "market".
	OrderType string `json:"order_type,omitempty"`
	// Whether the order was placed before the event started.
	PlacedPreStart bool `json:"placed_pre_start,omitempty"`
	// Limit price, below the market's `max_price`; read that per market rather
	// than assuming a ceiling. Absent for market orders. In dollars. Carries up to
	// 7 decimal places; parse money with a variable-scale decimal type, not a
	// fixed-width one. Money as a decimal string, exactly as sent by the API.
	Price Decimal `json:"price,omitempty"`
	// Order size in contracts. Quantity as a decimal string, exactly as sent by
	// the API.
	Quantity Decimal `json:"quantity,omitempty"`
	// The rejection reason, if the order was rejected.
	RejectionReason string `json:"rejection_reason,omitempty"`
	// Order state, one of nine. See [Market and order
	// status](/concepts/market-status/#order-statuses) for the full set and which
	// are terminal. One of: "created", "requested", "accepted", "delayed", "open",
	// "filled", "rejected", "cancelled", "partially_cancelled".
	Status string `json:"status,omitempty"`
	// The ISO-8601 timestamp of the time the order was placed.
	Time time.Time `json:"time,omitzero"`
	// Total premium across all fills on this order. In dollars. Money as a decimal
	// string, exactly as sent by the API.
	TotalValue Decimal `json:"total_value,omitempty"`
}

